import br.com.swconsultoria.nfe.exception.NfeException;
import com.fasterxml.jackson.core.type.TypeReference;
import org.junit.Test;

import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.*;

public class GetTests {

    // Helper class for complex type test
    public static class TestPojo {
        private String name;
        private int value;

        public String getName() {
            return name;
        }

        public void setName(String name) {
            this.name = name;
        }

        public int getValue() {
            return value;
        }

        public void setValue(int value) {
            this.value = value;
        }
    }

    @Test
    public void testGetSuccess() throws Exception {
        String jsonInput = "{\"name\":\"Test\",\"value\":123}";
        TypeReference<TestPojo> typeRef = new TypeReference<TestPojo>() {};

        // Using reflection helper to mock the private static method getJson
        Mocks mock = new Mocks(jsonInput);

        ConfiguracoesNfe config = new ConfiguracoesNfe();
        Map<String, String> queryParams = new HashMap<>();

        TestPojo result = mock.get(config, queryParams, typeRef);

        assertNotNull(result);
        assertEquals("Test", result.getName());
        assertEquals(123, result.getValue());
    }

    @Test
    public void testGetThrowsNfeException() throws Exception {
        final NfeException expectedException = new NfeException("Config error");
        TypeReference<String> typeRef = new TypeReference<String>() {};

        Mocks mock = new Mocks(expectedException);

        ConfiguracoesNfe config = new ConfiguracoesNfe();
        Map<String, String> queryParams = new HashMap<>();

        try {
            mock.get(config, queryParams, typeRef);
            fail("Expected NfeException");
        } catch (NfeException e) {
            assertEquals("Config error", e.getMessage());
        }
    }

    @Test
    public void testGetThrowsIOException() throws Exception {
        final IOException expectedException = new IOException("Network error");
        TypeReference<String> typeRef = new TypeReference<String>() {};

        Mocks mock = new Mocks(expectedException);

        ConfiguracoesNfe config = new ConfiguracoesNfe();
        Map<String, String> queryParams = new HashMap<>();

        try {
            mock.get(config, queryParams, typeRef);
            fail("Expected IOException");
        } catch (IOException e) {
            assertEquals("Network error", e.getMessage());
        }
    }

    @Test
    public void testGetWithStringType() throws Exception {
        String jsonInput = "simple string";
        TypeReference<String> typeRef = new TypeReference<String>() {};

        Mocks mock = new Mocks("\"" + jsonInput + "\"");

        ConfiguracoesNfe config = new ConfiguracoesNfe();
        Map<String, String> queryParams = new HashMap<>();

        String result = mock.get(config, queryParams, typeRef);
        assertEquals(jsonInput, result);
    }

    @Test
    public void testGetWithEmptyMap() throws Exception {
        String jsonInput = "[]";
        TypeReference<TestPojo[]> typeRef = new TypeReference<TestPojo[]>() {};

        Mocks mock = new Mocks(jsonInput);

        ConfiguracoesNfe config = new ConfiguracoesNfe();
        Map<String, String> emptyParams = new HashMap<>();

        TestPojo[] result = mock.get(config, emptyParams, typeRef);
        assertNotNull(result);
        assertEquals(0, result.length);
    }

    /**
     * Helper class to extend ConsultaTributacao to make the protected get() method accessible
     * and override the behavior of the private getJson() method.
     * Note: This relies on the implementation detail that get() calls getJson().
     */
    private static class Mocks extends ConsultaTributacao {
        private final String mockJson;
        private final Exception mockException;

        public Mocks(String mockJson) {
            this.mockJson = mockJson;
            this.mockException = null;
        }

        public Mocks(Exception mockException) {
            this.mockJson = null;
            this.mockException = mockException;
        }

        // We define a new instance method here. When ConsultaTributacao.get() calls getJson(),
        // standard Java polymorphism applies. If get() is implemented to call this.getJson(),
        // this instance method will be invoked instead of the private static one.
        public String getJson(ConfiguracoesNfe config, Map<String, String> queryParams) throws NfeException, IOException {
            if (mockException != null) {
                if (mockException instanceof NfeException) {
                    throw (NfeException) mockException;
                } else if (mockException instanceof IOException) {
                    throw (IOException) mockException;
                }
            }
            return mockJson;
        }
    }
}
